    if (!jobIds || !jobIds.length) return null;
    var result = await api("/jobs/purge", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ job_ids: jobIds, delete_data: deleteData === true }),
    });
