  function yFor(v) { return pad.top + (1 - ((v - yDom[0]) / (yDom[1] - yDom[0] || 1))) * Ph; }
  var visiblePoints = points.filter(function(p) { return p.x >= xDom[0] && p.x <= xDom[1] && p.y >= yDom[0] && p.y <= yDom[1]; });
