  if (hasMin) items += '<span class="energy-legend-item"><i class="energy-legend-swatch min"></i>最低能量</span>';
  if (hasFailed) items += '<span class="energy-legend-item"><i class="energy-legend-swatch failed"></i>未收敛</span>';
