        stageCount: stageCount,
        stageBar: stageBar,
        stageFill: stageFill,
        stageDetail: stageDetail,
        stageStrip: stageStrip,
        grid: grid,
        failure: failure,
        artifactSection: artifactSection,
        artifactNote: artifactNote,
        artifactList: artifactList,
        artifactRetry: artifactRetry,
